vec3 uv2 = multiply(vec3((uv-.5)*MinDistB(uv),MinDistB(uv))/myzoom,RotMat)+CamPos;
glow = pow (sat(texture(sampler_noise_hq,.02*uv2).r-.6) * 2.0, 2.0 );
//uv += .003*glow*(texture(sampler_noise_mq, uv * 2.0+vec2( 0.0 ,uTime / 4.0).xy-.5));
float focus = sat(abs(GetDistB2(uv)-dist_c) * 1.0+.2);
float struc = GetBlurX(uv,focus).r;
glow = sat(1.0 - exp(-(GetBlur1(uv).r))-.2);
q18 = 1;
ret = pow(struc, 1.0 ) * (.2+(1.0 - focus) *mix(dist,1.0 - dist,q18)) * (1+.5*sin(uv2));
ret = mix(ret, vec3( 0.0 , 1.0 ,glow * 3.0), glow);
//distant light
//ret += pow(1.0 - GetBlurX(uv,.8).b, 3.0 )*(.5+.5*slow_roam_cos) *q19;
//Lamp
uv3 = uv1;
lamp = clamp01(1-4*length(uv3))*(struc)*clamp01(1-2*bdist)*1.8;
ret += (1.0 - lum(ret))*lamp;
ret = vec3( 1.0 ) - exp((-2)*ret);
//ret = GetPixel(uv).r;
// laser
ret = ret + dots*(1.0 + ret);
}
//-------------------------------------------
//Written by martin
  fragColor = vec4(ret, 1.0);
}

